// One item per keyword. One keyword per line (commas and semicolons also separate).
const MAX = 10; // SerpApi free tier: 50 searches/hour, 250/month
const form = $input.first().json;
const marketplace = form.Marketplace || 'amazon.com';

const seen = new Set();
const list = [];
const junk = [];
for (const part of String(form.Keywords || '').split(/[\n,;]+/)) {
  const k = part.toLowerCase()
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^[^a-z0-9]+|[^a-z0-9]+$/g, ''); // strip punctuation at the ends: "rubber bands!!!" -> "rubber bands"
  if (!k) {
    if (part.trim()) junk.push(part.trim()); // something was typed, but no letters or digits
    continue;
  }
  if (seen.has(k)) continue;
  seen.add(k);
  list.push(k);
}
if (list.length === 0) {
  throw new Error(`No keywords entered.${junk.length ? ` Ignored ${junk.join(' ')} because it has no letters or digits.` : ''}`);
}

const kept = list.slice(0, MAX);
const dropped = list.slice(MAX);
const batchId = $now.toFormat('yyyy-MM-dd HH:mm:ss') + ' PKT';

return kept.map((keyword, i) => ({
  json: {
    batch_id: batchId,
    order: i + 1,
    keyword,
    marketplace,
    dropped: dropped.join(', '),
  },
}));

// Bundle everything the core needs into ONE item: each keyword with its raw search, plus the saved history.
// Search results line up with Split Keywords by position (one search per keyword, failures included).
const requests = $('Split Keywords').all().map(i => i.json);
const responses = $('Search Amazon (SerpApi)').all().map(i => i.json);
const history = $('Read History').all().map(i => i.json).filter(r => r.run_id);
return [{
  json: {
    tool: 'i1',
    batch_id: requests[0].batch_id,
    searches: requests.map((req, idx) => ({ order: req.order, keyword: req.keyword, marketplace: req.marketplace, response: responses[idx] ?? { error: 'no response' } })),
    history,
    dropped: (requests[0].dropped || '').split(', ').filter(Boolean),
  },
}];

// ---- Result page: shared design (Amazon Toolkit). Presentation only: every value is copied from earlier nodes. ----
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const CURS = { 'amazon.com': '$', 'amazon.co.uk': '£', 'amazon.ca': 'C$' };
const num = v => (v === '' || v === null || v === undefined || Number.isNaN(Number(v)) ? null : Number(v));
const int = v => (num(v) === null ? '–' : Math.round(num(v)).toLocaleString('en-US'));
const money = (v, cur) => (num(v) === null ? '–' : `${cur}${num(v).toFixed(2)}`);
const big = (v, cur = '') => { const n = num(v); if (n === null) return '–'; if (n >= 1e6) return `${cur}${(n / 1e6).toFixed(2)}M`; if (n >= 1e4) return `${cur}${Math.round(n / 1e3)}K`; return `${cur}${int(n)}`; };
const rating = v => (num(v) === null ? '–' : num(v).toFixed(1));
const spots = t => esc(String(t ?? '').split(' | ').join(' · '));
const split = t => String(t ?? '').split(' | ').map(s => s.trim()).filter(Boolean);
const LEVEL = { high: 'yes', medium: 'mid', low: 'no' };
const pill = (text, kind) => `<span class="pill ${kind || ''}">${esc(text)}</span>`;
const levelPill = t => pill(t, LEVEL[String(t || '').toLowerCase()] || 'muted');
const tiles = list => `<div class="tiles">${list.map(([v, l]) => `<div class="tile"><div class="tv">${v}</div><div class="tl">${esc(l)}</div></div>`).join('')}</div>`;
const section = (title, body) => (body ? `<section><h2>${esc(title)}</h2>${body}</section>` : '');
const table = (head, rows, right = []) => `<div class="tw"><table><thead><tr>${head.map((h, i) => `<th${right.includes(i) ? ' class="r"' : ''}>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td${right.includes(i) ? ' class="r"' : ''}>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const notesList = list => (list.length ? `<ul class="notes">${list.map(n => `<li>${esc(n)}</li>`).join('')}</ul>` : '');
const chips = list => (list.length ? `<div class="chips">${list.map(c => `<span class="chip">${esc(c)}</span>`).join('')}</div>` : '');

function page({ code, tool, colour, tint, title, meta, verdict, body, saved, cannotTell }) {
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(tool)} · ${esc(title)}</title>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600&family=Source+Serif+4:opsz,wght@8..60,600&display=swap');
*{box-sizing:border-box}
body{margin:0;background:${tint};color:#1f2328;font:14px/1.55 Inter,'Segoe UI',Helvetica,Arial,sans-serif}
.wrap{max-width:760px;margin:0 auto;padding:28px 16px 48px}
.card{background:#fff;border:1px solid #e2ddd5;border-radius:6px;overflow:hidden;box-shadow:0 8px 28px rgba(13,27,42,.08)}
header{background:${colour};color:#fff;padding:26px 28px 22px;border-bottom:5px solid #9C7A3C}
.label{font:12px/1 ui-monospace,Consolas,monospace;letter-spacing:3px;color:#D8CBB8;text-transform:uppercase}
h1{font:600 30px/1.2 'Source Serif 4',Georgia,serif;margin:10px 0 6px}
.meta{color:#D8CBB8;font-size:13px}
.verdict{padding:22px 28px;border-bottom:1px solid #eee7dc;background:#fbfaf7}
.verdict .big{font:600 22px/1.3 'Source Serif 4',Georgia,serif;color:${colour}}
.verdict p{margin:6px 0 0;color:#3d434a}
.content{padding:6px 28px 26px}
section{margin-top:22px}
h2{font:600 12px/1 Inter,sans-serif;letter-spacing:2px;text-transform:uppercase;color:${colour};margin:0 0 10px;padding-bottom:8px;border-bottom:2px solid #9C7A3C;display:inline-block}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:10px;margin-top:4px}
.tile{border:1px solid #e2ddd5;border-top:3px solid ${colour};border-radius:4px;padding:12px 14px;background:#fff}
.tv{font:600 20px/1.2 'Source Serif 4',Georgia,serif;color:#1f2328}
.tl{font-size:12px;color:#5f6670;margin-top:4px}
.tw{overflow-x:auto;border:1px solid #e2ddd5;border-radius:4px}
table{border-collapse:collapse;width:100%;font-size:13px}
th{background:#f7f5f2;color:#3d434a;font-weight:600;text-align:left;padding:8px 10px;border-bottom:1px solid #e2ddd5;white-space:nowrap}
td{padding:8px 10px;border-bottom:1px solid #f0ece5;vertical-align:top}
tbody tr:nth-child(even) td{background:#fcfbf9}
tbody tr:last-child td{border-bottom:0}
.r{text-align:right;white-space:nowrap}
.sub{color:#5f6670;font-size:12px}
.pill{display:inline-block;padding:2px 9px;border-radius:999px;font-size:12px;font-weight:600;white-space:nowrap;background:#eceae6;color:#3d434a}
.pill.yes{background:#014D4E;color:#fff}.pill.mid{background:#301934;color:#fff}.pill.no{background:#DC143C;color:#fff}.pill.muted{background:#eceae6;color:#5f6670}
.notes{margin:0;padding-left:18px;color:#3d434a}.notes li{margin:4px 0}
.chips{display:flex;flex-wrap:wrap;gap:6px}
.chip{border:1px solid #d6d0c6;border-radius:999px;padding:3px 10px;font-size:12px;color:#5f6670;background:#fff}
.item{border-left:3px solid ${colour};padding:10px 14px;margin:10px 0;background:#fbfaf7;border-radius:0 4px 4px 0}
.item b{color:#1f2328}
.paste{width:100%;min-height:236px;font:13px/1.6 ui-monospace,Consolas,monospace;border:1px solid #d6d0c6;border-radius:4px;padding:10px;background:#fff;color:#1f2328;resize:vertical}
.btn{margin-top:8px;background:${colour};color:#fff;border:0;border-radius:4px;padding:9px 16px;font:600 13px Inter,sans-serif;cursor:pointer}
footer{padding:14px 28px;border-top:1px solid #eee7dc;color:#5f6670;font-size:12px;background:#fbfaf7}
@media (max-width:560px){header,.verdict,.content,footer{padding-left:18px;padding-right:18px}h1{font-size:24px}}
</style></head><body><div class="wrap"><div class="card">
<header><div class="label">Amazon Toolkit · ${esc(code)} ${esc(tool)}</div><h1>${esc(title)}</h1><div class="meta">${meta.map(esc).join(' &nbsp;·&nbsp; ')}</div></header>
${verdict ? `<div class="verdict">${verdict}</div>` : ''}
<div class="content">${body}
${section('Cannot tell from this data', chips(cannotTell || []))}
</div>
<footer>Saved to the sheet: ${esc(saved)}. Every number recomputes from the Listings tab.</footer>
</div></div></body></html>`;
}
// i1 Market Screener: result page
const core = $('Toolkit Core').first().json;
const markets = [...(core.markets || [])].sort((a, b) => a.rank - b.rank);
const kws = core.keywords || [];
const first = markets[0] || {};
const mk = first.marketplace || (kws.find(k => k.marketplace) || {}).marketplace || '';
const cur = CURS[mk] || '';
const batch = first.batch_id || (kws[0] || {}).batch_id || '';
const notDone = kws.filter(k => k.status && k.status !== 'ok');
const parts = v => (Array.isArray(v) ? v : split(v));
const verdict = first.market ? `<div class="big">#1 ${esc(first.market)} · ${esc(first.opportunity_score)}/100</div>
<p>${levelPill(first.confidence)} &nbsp;${esc(first.vs_next || 'Only one market screened.')}</p>` : '<div class="big">No market could be scored</div>';
const rows = markets.map(m => [
  `<b>${esc(m.rank)}</b>`,
  `<b>${esc(m.market)}</b>${String(m.keywords || '').includes(',') ? `<div class="sub">${esc(m.keywords)}</div>` : ''}${m.sub_segment_of ? `<div class="sub">sub-segment of ${esc(m.sub_segment_of)}</div>` : ''}`,
  `<b>${esc(m.opportunity_score)}</b>`, levelPill(m.confidence), money(m.price_median, cur), `${int(m.units_last_month_floor)}+`,
  `${esc(m.top_brand || '–')}<div class="sub">${esc(m.top_brand_sales_share_pct)}% share</div>`,
]);
const why = parts(first.score_breakdown).map(s => {
  const t = String(s).match(/^openness ([\d.]+)\/100 x demand ([\d.]+): at least (\d+) in sales last month on page 1 ?(.*)$/);
  if (t) return ['<b>score</b>', `<b>${esc(t[1])} × ${esc(t[2])}</b>`, `openness × demand. At least ${big(t[3], cur)} in sales last month on page 1 ${esc(t[4])}`];
  const m = String(s).match(/^(\S+) ([\d.]+\/\d+): (.*)$/);
  return m ? [esc(({ low_review_sales: 'sales to newcomers' })[m[1]] || m[1].replace(/_/g, ' ')), `<b>${esc(m[2])}</b>`, esc(m[3])] : ['', '', esc(s)];
});
const html = page({
  code: 'i1', tool: 'Market Screener', colour: '#1B3A6B', tint: '#eef2f8',
  title: `${markets.length} market${markets.length === 1 ? '' : 's'} ranked`,
  meta: [mk, batch, `${kws.filter(k => k.status !== 'skipped').length} keywords searched`],
  verdict,
  body: [
    section('Ranking', table(['#', 'Market', 'Score', 'Confidence', 'Median price', 'Bought last month', 'Top brand'], rows, [2, 4, 5])),
    first.market ? section(`Why #1 scored ${first.opportunity_score}`, table(['Part', 'Points', 'Because'], why, [1])) : '',
    first.confidence_notes ? section('What lowers confidence in #1', notesList(parts(first.confidence_notes))) : '',
    section('Not analyzed', notesList(notDone.map(k => `${k.keyword}: ${k.note || k.status}`))),
  ].join(''),
  saved: 'Markets, Keywords, Listings',
  cannotTell: parts(first.cannot_tell),
});
return [{ json: { html } }];

